import { z } from 'zod';
import { objectId, pageQuery } from './common';
import { LIMITS } from './limits';

export const startDmInput = z.object({ userId: objectId });

export const attachmentInput = z.object({
  /** Server path returned by the attachment upload endpoint. */
  url: z.string().max(300),
  name: z.string().max(200),
  mimeType: z.string().max(120),
  size: z.number().int().nonnegative(),
});

export const sendMessageInput = z
  .object({
    /** Generated by the app. The same id sent twice produces one message. */
    clientMessageId: z.string().min(8).max(64),
    body: z.string().trim().max(LIMITS.messageMax).default(''),
    replyToId: objectId.optional(),
    threadRootId: objectId.optional(),
    attachments: z.array(attachmentInput).max(1).default([]),
  })
  .refine((value) => value.body.length > 0 || value.attachments.length > 0, {
    message: 'A message needs text or an attachment',
    path: ['body'],
  });
export type SendMessageInput = z.input<typeof sendMessageInput>;

export const editMessageInput = z.object({ body: z.string().trim().min(1).max(LIMITS.messageMax) });
export const reactInput = z.object({ emoji: z.string().min(1).max(16) });
export const markReadInput = z.object({ messageId: objectId });
export const messagesQuery = pageQuery.extend({ threadRootId: objectId.optional() });
export const typingInput = z.object({ conversationId: objectId, typing: z.boolean() });

export type ConversationType = 'dm' | 'group' | 'club';
export type MemberRole = 'admin' | 'member';

/** The few user fields shown next to a message or in a member list. */
export type UserChip = {
  id: string;
  name: string;
  username: string;
  avatarUrl: string | null;
  /** The student's school color, or null before onboarding. */
  color: string | null;
};

export type Attachment = { url: string; name: string; mimeType: string; size: number };
export type Reaction = { emoji: string; userIds: string[] };

export type Message = {
  id: string;
  conversationId: string;
  clientMessageId: string;
  sender: UserChip;
  type: 'text' | 'image' | 'file';
  /** Empty when the message was deleted. */
  body: string;
  attachments: Attachment[];
  replyTo: { id: string; body: string; senderName: string; deleted: boolean } | null;
  threadRootId: string | null;
  threadReplyCount: number;
  reactions: Reaction[];
  edited: boolean;
  deleted: boolean;
  createdAt: string;
};

export type ConversationSummary = {
  id: string;
  type: ConversationType;
  /** Group or club name, or the other student's name for a DM. */
  title: string;
  imageUrl: string | null;
  color: string | null;
  /** DM only: the other student. */
  peer: (UserChip & { online: boolean }) | null;
  clubId: string | null;
  lastMessage: { body: string; senderName: string; createdAt: string } | null;
  unreadCount: number;
  memberCount: number;
  myRole: MemberRole;
};

export type ConversationDetail = ConversationSummary & {
  description: string;
  /** For each other member, the last message they have read. Drives "read" ticks in DMs. */
  readBy: { userId: string; messageId: string | null }[];
};

/** Events the server pushes over the socket. */
export type ServerEvents = {
  'message:new': (message: Message) => void;
  'message:updated': (message: Message) => void;
  'conversation:read': (event: { conversationId: string; userId: string; messageId: string }) => void;
  'conversation:changed': (event: { conversationId: string }) => void;
  'conversation:removed': (event: { conversationId: string }) => void;
  typing: (event: { conversationId: string; userId: string; name: string; typing: boolean }) => void;
  presence: (event: { userId: string; online: boolean }) => void;
};

export type Ack<T> = { ok: true; data: T } | { ok: false; error: { code: string; message: string } };

/** Events the app sends over the socket. */
export type ClientEvents = {
  'message:send': (
    payload: SendMessageInput & { conversationId: string },
    ack: (result: Ack<Message>) => void,
  ) => void;
  typing: (payload: { conversationId: string; typing: boolean }) => void;
};
